<template><section aria-label="富文本转纯文本"><p class="tool-note">粘贴 HTML 源码，或在下方粘贴区直接粘贴网页/文档内容。不会把 HTML 插入网页执行；保留段落、换行、列表和表格文本，忽略脚本与样式。</p><div class="rich-paste" contenteditable="true" role="textbox" aria-label="富文本粘贴区" data-placeholder="点击这里，粘贴富文本" @paste.prevent="paste" @drop.prevent></div><div class="tool-two-column"><label class="tool-label">HTML 源码<textarea v-model="input" aria-label="富文本 HTML 源码" spellcheck="false"></textarea></label><label class="tool-label">纯文本结果<textarea v-model="output" aria-label="富文本纯文本结果"></textarea></label></div><div class="tool-actions"><button type="button" @click="convert">提取纯文本</button><button type="button" :disabled="!output" @click="copy">复制纯文本</button><button type="button" :disabled="!output" @click="download">下载纯文本 TXT</button><button type="button" @click="clear">清空富文本</button></div><p role="status">{{message}}</p></section></template>
<script>
import {richTextToPlain} from '../../utils/language-privacy-tools.mjs';
import {downloadBlob} from '../../utils/utility-tools.mjs';
export default {name:'RichTextTool',data:()=>({input:'',output:'',message:''}),methods:{paste(event){const html=event.clipboardData?.getData('text/html'),plain=event.clipboardData?.getData('text/plain')||'';this.input=html||plain.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/\n/g,'<br>');this.convert();event.currentTarget.textContent=this.output;},convert(){try{this.output=richTextToPlain(this.input);this.message='纯文本提取完成';}catch(error){this.output='';this.message=error.message;}},async copy(){try{await navigator.clipboard.writeText(this.output);this.message='已复制纯文本';}catch{this.message='复制未完成，请选中文本手动复制';}},download(){downloadBlob(new Blob([this.output],{type:'text/plain;charset=utf-8'}),'01-plain-text.txt');},clear(){this.input='';this.output='';this.message='';this.$el.querySelector('.rich-paste').textContent='';}}};
</script>
<style scoped>.rich-paste{min-height:72px;padding:12px;border:1px dashed var(--el-border-color);border-radius:8px;white-space:pre-wrap;overflow-wrap:anywhere;}.rich-paste:empty:before{content:attr(data-placeholder);color:var(--el-text-color-secondary);}</style>
